        if (!type || !/^(views\/)?[\w.-]+$/.test(name) || !fs2.existsSync(path2.join(__dirname, "web", name))) return send(res, 404, { error: "not found" });
        res.writeHead(200, { "content-type": `${type}; charset=utf-8`, "cache-control": "no-cache", ...CORS });
